import { CameraRigNode, Input, Node, dampTime } from 'cleo'
import { angleDiff, planarDistance, yawTo } from '@/Core/Scripts/SoulsMath'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * Hollow Keep — the third-person camera with target lock. Attach to the Player's `camera rig`, a Camera
 * Rig node that sits BEFORE the Player Controller among the Player's children.
 *
 * Free: an ordinary orbit camera the controller steers with Look.
 *
 * Locked: the rig switches to `aimMode = 'lookAt'` on the target's `LockPoint`, so the camera holds the
 * enemy in frame by itself. The controller keeps writing the rig's yaw into the intent as the aim, which
 * is what makes the player STRAFE around the target — SoulsPlayer sets `facingMode = 'aim'` while locked.
 *
 *   LockOn                   toggle. With nothing to lock, it re-centres the camera behind the player.
 *   SwitchTargetLeft/Right   cycle (keys); a hard flick of the right stick or the mouse does the same
 *
 * Candidates are the manager's live enemies within `lockRange` and in line of sight, ranked by angle off
 * the camera's forward and then by distance (rankLockTargets, below). The lock breaks past
 * `breakRange`, after `losBreakSeconds` behind a wall, or when the target dies — in which case another
 * enemy within `retargetRange` is picked up, as the games do.
 *
 * The reticle is a world-space UI Root named `LockReticle`, a child of the player beside this rig. Its
 * `uiTargetId` is kept pointed at the
 * target's lock point.
 *
 * Framing: while locked, the boom eases in to `lockedArmLength` and over the shoulder to
 * `lockedSocketOffset`, so the fight fills the frame; unlocking eases it back out to the authored values.
 * Both blend over `lockBlendSeconds` — the rig itself does not damp its arm, so a snap would be a cut.
 */
export default class SoulsLockOnNode extends CameraRigNode {
  public lockRange: number = 20
  public breakRange: number = 26
  /** Seconds the target may stay hidden behind geometry before the lock lets go. */
  public losBreakSeconds: number = 1.5
  /** Seconds between two target switches, so one flick switches once. */
  public switchCooldown: number = 0.35
  /** Right-stick deflection (scaled ×4 in the map) that counts as a flick. */
  public stickFlick: number = 2.6
  /**
   * Mouse speed, in pixels per SECOND, that counts as a flick. A per-frame pixel threshold made switching
   * targets harder the higher the frame rate, since the same flick is spread over more frames.
   */
  public mouseFlickPerSecond: number = 2700
  /** Pitch limits while locked (positive looks down). Keeps a tall boss from flipping the camera. */
  public lockedPitchMin: number = -25
  public lockedPitchMax: number = 35
  public reticleName: string = 'LockReticle'
  /** When the target dies, the lock jumps to another enemy only if one is this close. */
  public retargetRange: number = 10
  /** Boom length while locked: closer than the free camera, for a tighter view of the fight. */
  public lockedArmLength: number = 2.3
  /**
   * Pivot offset while locked (rig space: +X is the rig's LEFT, +Y up) — negative X, so the camera sits
   * over the RIGHT shoulder and the target is framed past it.
   */
  public lockedSocketOffset: [number, number, number] = [-0.6, 0.15, 0]
  /** Seconds the camera takes to move in on a lock, and back out on release. */
  public lockBlendSeconds: number = 0.3

  /** The locked enemy (a SoulsEnemy root), or null. SoulsPlayer reads this. */
  public lockTarget: Node = null

  private _gm: Node = null
  private _player: Node = null
  private _reticle: Node = null
  private _hiddenFor: number = 0
  private _switchWait: number = 0
  private _freePitchMin: number = -80
  private _freePitchMax: number = 80
  private _freeArmLength: number = 4
  private _freeSocket: [number, number, number] = [0, 0, 0]

  onStart() {
    this._gm = this.findNode('GameManager')
    this._player = this.parent
    // The reticle is the player's (a sibling of this rig, inside the Player template).
    this._reticle = this._player?.getChildByName(this.reticleName)[0] ?? null
    this._freePitchMin = this.pitchMin
    this._freePitchMax = this.pitchMax
    this._freeArmLength = this.armLength
    this._freeSocket = [this.socketOffset[0], this.socketOffset[1], this.socketOffset[2]]
    this.aimMode = 'orbit'
    this._showReticle(null)
    // Start behind the player, whichever way the level placed them: the orbit's yaw is a world angle
    // and does not follow the player's own rotation.
    if (this._player) {
      const f = this._player.worldForward
      this.yaw = Math.atan2(f[0], f[2]) * 180 / Math.PI
    }
  }

  onUpdate(delta: number) {
    this._switchWait = Math.max(0, this._switchWait - delta)
    const player = this._player as any
    if (player?.isDead) { if (this.lockTarget) this.unlock(); return }

    if (Input.started('LockOn')) {
      if (this.lockTarget) this.unlock()
      else if (!this._lockBest()) this._recenter()
    }
    // Every frame, locked or not, so a release eases back out rather than stopping where it was. Runs
    // before the rig's lateUpdate, so the boom it builds this frame already uses these values.
    this._frame(delta)
    if (!this.lockTarget) return

    // Lost?
    const target = this.lockTarget as any
    if (!target || target.isDead || target.spawned === false || !this.scene?.getNodeById(this.lockTarget.id)) {
      this.onTargetDied(this.lockTarget)
      return
    }
    const me = this._player.worldPosition
    const at = this.lockTarget.worldPosition
    if (Math.hypot(at[0] - me[0], at[2] - me[2]) > this.breakRange) { this.unlock(); return }
    this._hiddenFor = this._hasLineOfSight(this.lockTarget) ? 0 : this._hiddenFor + delta
    if (this._hiddenFor > this.losBreakSeconds) { this.unlock(); return }

    // Switching.
    let dir = 0
    if (Input.started('SwitchTargetLeft')) dir = 1
    if (Input.started('SwitchTargetRight')) dir = -1
    if (!dir && this._switchWait <= 0) {
      const look = Input.vector('Look')
      const device = Input.device('Look')
      // A stick is a deflection; a mouse delta is distance this frame, so it is turned into a speed.
      const amount = device === 'gamepadAxis' ? Math.abs(look[0]) : Math.abs(look[0]) / Math.max(delta, 1e-3)
      const flick = device === 'gamepadAxis' ? this.stickFlick : this.mouseFlickPerSecond
      // Look X is positive to the RIGHT; right means a clockwise (negative) yaw step.
      if (amount >= flick) dir = look[0] > 0 ? -1 : 1
    }
    if (dir) this._switch(dir)
  }

  /** Drop the lock and hand the camera back to the player. */
  public unlock(): void {
    this.lockTarget = null
    this.aimMode = 'orbit'
    this.lookAtId = null
    this.pitchMin = this._freePitchMin
    this.pitchMax = this._freePitchMax
    this._hiddenFor = 0
    this._showReticle(null)
  }

  /** The manager calls this when any enemy dies; only our target matters. */
  public onTargetDied(enemy: Node): void {
    if (!this.lockTarget || enemy !== this.lockTarget) return
    this.unlock()
    const near = this._candidates().find(c => {
      const me = this._player.worldPosition
      return Math.hypot(c.position[0] - me[0], c.position[2] - me[2]) <= this.retargetRange
    })
    if (near) this.lockOnto(near.node)
  }

  /** Lock onto a specific enemy (e.g. the boss when its fight starts). */
  public lockOnto(enemy: Node): void {
    if (!enemy) return
    const point = this._lockPoint(enemy)
    this.lockTarget = enemy
    this.aimMode = 'lookAt'
    this.lookAtId = point.id
    this.lookAtOffset = [0, 0, 0]
    this.pitchMin = this.lockedPitchMin
    this.pitchMax = this.lockedPitchMax
    this._hiddenFor = 0
    this._showReticle(point)
  }

  private _lockBest(): boolean {
    const best = this._candidates()[0]
    if (!best) return false
    this.lockOnto(best.node)
    playSound(this, 'Lock On')
    return true
  }

  /** Step to the next candidate clockwise (dir -1) or counter-clockwise (dir +1) of the current one. */
  private _switch(dir: number): void {
    this._switchWait = this.switchCooldown
    const current = this.lockTarget
    const me = this._player.worldPosition
    const base = yawTo(me, current.worldPosition)
    let best: Node = null
    let bestStep = Infinity
    for (const c of this._candidates()) {
      if (c.node === current) continue
      // How far round in the requested direction this candidate is, 0..360.
      let step = (yawTo(me, c.position) - base) * dir
      step = ((step % 360) + 360) % 360
      if (step > 0 && step < bestStep) { bestStep = step; best = c.node }
    }
    if (best) this.lockOnto(best)
  }

  private _candidates(): { node: Node, position: ArrayLike<number> }[] {
    const gm = this._gm as any
    if (!gm?.liveEnemies || !this._player) return []
    const me = this._player.worldPosition
    // Range BEFORE line of sight: the ray is the expensive half (a long one over the terrain walks every
    // cell under it), and an enemy out of range is never a candidate whatever it can see.
    const list = gm.liveEnemies()
      .filter((e: Node) => planarDistance(me, e.worldPosition) <= this.lockRange)
      .filter((e: Node) => this._hasLineOfSight(e))
      .map((e: Node) => ({ node: e, position: e.worldPosition }))
    return this.rankLockTargets(me, this.yaw, list, this.lockRange)
  }

  /** Ease the boom toward the locked framing, or back to the free one. */
  private _frame(delta: number): void {
    const locked = !!this.lockTarget
    const s = this.lockBlendSeconds
    this.armLength = dampTime(this.armLength, locked ? this.lockedArmLength : this._freeArmLength, s, delta)
    const to = locked ? this.lockedSocketOffset : this._freeSocket
    for (let i = 0; i < 3; i++) this.socketOffset[i] = dampTime(this.socketOffset[i], to[i], s, delta)
  }

  /**
   * Order lock-on candidates: smallest angle off the camera's forward first, distance breaking ties in
   * 10-degree buckets so two enemies side by side resolve to the nearer.
   */
  public rankLockTargets(origin: ArrayLike<number>, yawDeg: number, candidates: any[], maxRange: number): any[] {
    return candidates
      .map(c => ({ c, d: planarDistance(origin, c.position), a: Math.abs(angleDiff(yawTo(origin, c.position), yawDeg)) }))
      .filter(x => x.d <= maxRange)
      .sort((x, y) => (Math.floor(x.a / 10) - Math.floor(y.a / 10)) || (x.d - y.d))
      .map(x => x.c)
  }

  /** Line of sight from the camera pivot to the enemy's lock point, ignoring characters. */
  private _hasLineOfSight(enemy: Node): boolean {
    const physics = this.scene?.physics as any
    if (!physics?.raycast) return true
    const from = this.worldPosition
    const to = this._lockPoint(enemy).worldPosition
    const hit = physics.raycast([from[0], from[1], from[2]], [to[0], to[1], to[2]], {
      reject: (owner: Node) => !!owner && (owner.nodeType === 'character'
        || !!owner.getVariable?.('isEnemy') || !!owner.getVariable?.('isPlayer')),
    })
    return !hit
  }

  private _lockPoint(enemy: Node): Node {
    const e = enemy as any
    return (e.lockPoint ? e.lockPoint() : null) ?? enemy.getChildByName('LockPoint')[0] ?? enemy
  }

  /** Swing the camera behind the player — what pressing lock with nothing in range does. */
  private _recenter(): void {
    if (!this._player) return
    const f = this._player.worldForward
    this.setOrbit(Math.atan2(f[0], f[2]) * 180 / Math.PI, 12)
  }

  private _showReticle(point: Node): void {
    const reticle = this._reticle as any
    if (!reticle) return
    reticle.uiTargetId = point ? point.id : null
    if (reticle.visible !== !!point) reticle.visible = !!point
  }
}

import { Node, UIProgressBarNode, UIRootNode, UITextNode } from 'cleo'

/**
 * Hollow Keep — the PLAYER's HUD. Attach to the `HUD` node, a screen-space UI Root that is a CHILD of
 * the player (in the Player template): the HUD belongs to the character it shows, and reads that
 * character — its parent — not some node found by name. A second player would bring its own HUD.
 *
 * One script for the whole HUD. It finds its widgets by NAME once (missing ones are skipped, so you can
 * restyle or rebuild the HUD freely as long as the names stay) and writes them every frame from its
 * owner's public fields:
 *
 *   Health, HealthLag        uiProgressBar   HP, and the yellow "damage taken" bar that drains behind it
 *   Stamina                  uiProgressBar
 *   Estus                    uiText          flask count
 *   Weapon                   uiText          weapon in hand
 *   Souls, SoulsGain         uiText          souls held, and the +N popup
 *   Prompt / PromptText      uiPanel/uiText  "E  Rest at bonfire" — hidden when there is nothing to do
 *   Notice                   uiText          one-line messages ("Picked up ..."), fading
 *   Message / MessageTitle / MessageBody     the readable-message panel
 *
 * The boss bar is not here: it belongs to the boss (SoulsBossBar, inside the Hollow Warden template).
 *
 * Bars grow with their maximum (`pxPerHp`, `pxPerStamina`), so levelling Vigor visibly lengthens the bar.
 */
export default class SoulsHudNode extends UIRootNode {
  public pxPerHp: number = 0.75
  public pxPerStamina: number = 2.4
  public minBarWidth: number = 160
  public maxBarWidth: number = 900
  public noticeSeconds: number = 2.6
  /** Key shown in front of the interaction prompt. */
  public interactKey: string = 'E'

  private _player: Node = null
  private _w: any = {}
  private _barLeft: number = 48
  private _noticeAge: number = 99
  private _message: Node = null
  private _messageAge: number = 0

  onStart() {
    // The owner: the nearest ancestor that is a fighter (the Player the HUD is a child of).
    for (let n = this.parent; n; n = n.parent) if ((n as any).team) { this._player = n; break }
    for (const name of ['Health', 'HealthLag', 'HealthBack', 'Stamina', 'StaminaBack', 'Estus', 'Weapon', 'Souls',
      'SoulsGain', 'Prompt', 'PromptText', 'Notice', 'Message', 'MessageTitle', 'MessageBody']) {
      this._w[name] = this._find(name)
    }
    const health = this._w.Health as any
    if (health) this._barLeft = health.offsetMin[0]
    this._show('Message', false)
    this._show('Prompt', false)
    this._text('Notice', '')
    this._text('SoulsGain', '')
  }

  onUpdate(delta: number) {
    const p = this._player as any
    this._noticeAge += delta
    this._messageAge += delta

    if (p) {
      this._bar('Health', p.hp, p.maxHp)
      this._bar('HealthLag', p.hp, p.maxHp)
      this._width(['Health', 'HealthLag', 'HealthBack'], p.maxHp * this.pxPerHp)
      this._bar('Stamina', p.stamina, p.maxStamina)
      this._width(['Stamina', 'StaminaBack'], p.maxStamina * this.pxPerStamina)
      this._text('Estus', 'Estus Flask  ' + (p.estus ?? 0) + ' / ' + (p.estusMax ?? 0))
      this._text('Weapon', p.weaponName ?? '')
      this._text('Souls', String(Math.round(p.souls ?? 0)))
      this._text('SoulsGain', p.soulsGainAge < 2 && p.lastSoulsGain > 0 ? '+' + p.lastSoulsGain : '')

      const prompt = p.interactPrompt ?? ''
      this._show('Prompt', !!prompt && !this._message)
      if (prompt) this._text('PromptText', this.interactKey + '   ' + prompt)
    }

    if (this._noticeAge > this.noticeSeconds) this._text('Notice', '')

    // A message closes when the player walks out of its source's zone (closeMessageFrom), or dies.
    if (this._message && p?.isDead) this._closeMessage()
  }

  /** The character this HUD shows. */
  public get owner(): Node { return this._player }

  public showNotice(text: string): void {
    this._text('Notice', text)
    this._noticeAge = 0
  }

  /** Show a message; showing the SAME source again closes it (Interact toggles). */
  /** The player left `source`'s trigger zone: close its message if it is the one showing. */
  public closeMessageFrom(source: Node): void {
    if (this._message && this._message === source) this._closeMessage()
  }

  public showMessage(title: string, body: string, source: Node): void {
    if (this._message && this._message === source && this._messageAge > 0.15) { this._closeMessage(); return }
    this._message = source
    this._messageAge = 0
    this._text('MessageTitle', title)
    this._text('MessageBody', body)
    this._show('Message', true)
  }

  private _closeMessage(): void {
    this._message = null
    this._show('Message', false)
  }

  private _bar(name: string, value: number, max: number): void {
    const bar = this._w[name] as UIProgressBarNode
    if (!bar) return
    if (bar.max !== max) bar.max = Math.max(1, max)
    bar.value = Math.max(0, value)
  }

  private _width(names: string[], px: number): void {
    const width = Math.max(this.minBarWidth, Math.min(this.maxBarWidth, px))
    for (const name of names) {
      const node = this._w[name] as any
      if (!node) continue
      const right = node.offsetMin[0] + width
      if (Math.abs(node.offsetMax[0] - right) > 0.5) node.offsetMax = [right, node.offsetMax[1]]
    }
  }

  private _text(name: string, value: string): void {
    const node = this._w[name] as UITextNode
    if (node && node.text !== value) node.text = value
  }

  private _show(name: string, on: boolean): void {
    const node = this._w[name] as any
    if (node && node.visible !== on) node.visible = on
  }

  private _find(name: string): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }
}

import { Input, Node, UIButtonNode, UIRootNode, UITextNode } from 'cleo'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * Hollow Keep — the level-up menu shown while resting at a bonfire. Attach to the `BonfireMenu` node, a
 * screen-space UI Root authored hidden.
 *
 *   Card
 *     Title, LevelText, SoulsText, CostText, Derived, Help       uiText
 *     Row_Vigor / Row_Endurance / Row_Strength / Row_Dexterity     uiStack rows, each with
 *        Label (uiText)  Minus (uiButton)  Value (uiText)  Plus (uiButton)
 *     Confirm, Leave                                                uiButton
 *
 * Points are allocated as PENDING and cost nothing until Confirm, so the player can try a build and back
 * out. Each point costs the souls for one more level, priced by the player's own `levelCost`, so the total
 * of several points is the sum of consecutive levels. Every number shown comes from its owner: HP and
 * stamina from the player's curves, attack rating from each weapon.
 *
 * Keyboard/gamepad (the UI map): Navigate up/down picks a stat, left/right removes/adds a point, Submit
 * confirms, Cancel leaves. The mouse can click every button. The Gameplay map is disabled while open, so
 * the same keys do not also move the character.
 */
const STATS = ['vigor', 'endurance', 'strength', 'dexterity']

export default class SoulsBonfireMenuNode extends UIRootNode {
  public repeatDelay: number = 0.35
  public repeatRate: number = 0.09
  public selectedTint: [number, number, number, number] = [0.85, 0.65, 0.3, 0.35]
  public rowTint: [number, number, number, number] = [1, 1, 1, 0.04]
  public isOpen: boolean = false

  private _gm: Node = null
  private _player: Node = null
  private _pending: number[] = [10, 10, 10, 10]
  private _selected: number = 0
  private _navHeld: number = 0
  private _navRepeat: number = 0
  private _navLast: number[] = [0, 0]
  private _openedAt: number = 0
  private _clock: number = 0

  onStart() {
    this.visible = false
    this.isOpen = false
    const rows = ['Row_Vigor', 'Row_Endurance', 'Row_Strength', 'Row_Dexterity']
    rows.forEach((name, i) => {
      const row = this._find(name)
      if (!row) return
      const minus = this._find('Minus', row) as UIButtonNode
      const plus = this._find('Plus', row) as UIButtonNode
      if (minus) minus.onPress = () => { this._selected = i; this._adjust(-1) }
      if (plus) plus.onPress = () => { this._selected = i; this._adjust(1) }
    })
    const confirm = this._find('Confirm') as UIButtonNode
    if (confirm) confirm.onPress = () => this._confirm()
    const leave = this._find('Leave') as UIButtonNode
    if (leave) leave.onPress = () => this.close()
  }

  /** Called by the manager when the player rests. */
  public open(gm: Node, player: Node, bonfire: Node): void {
    this._gm = gm
    this._player = player
    this._resetPending()
    this._selected = 0
    this.isOpen = true
    this._openedAt = this._clock
    this.visible = true
    Input.disableMap('Gameplay')
    Input.releaseMouse()
    this._refresh()
  }

  public close(): void {
    if (!this.isOpen) return
    this.isOpen = false
    this.visible = false
    Input.enableMap('Gameplay')
    ;(this._gm as any)?.leaveBonfire?.()
  }

  onUpdate(delta: number) {
    this._clock += delta
    if (!this.isOpen) return
    // Swallow the press that opened us (Interact may share a key with Submit).
    if (this._clock - this._openedAt < 0.2) return

    const nav = Input.vector('Navigate')
    const dy = Math.abs(nav[1]) > 0.5 ? Math.sign(nav[1]) : 0
    const dx = Math.abs(nav[0]) > 0.5 ? Math.sign(nav[0]) : 0
    const fresh = dy !== this._navLast[1] || dx !== this._navLast[0]
    this._navLast = [dx, dy]
    let step = false
    if (dx || dy) {
      if (fresh) { step = true; this._navHeld = 0; this._navRepeat = 0 }
      else {
        this._navHeld += delta
        if (this._navHeld > this.repeatDelay) {
          this._navRepeat += delta
          if (this._navRepeat >= this.repeatRate) { this._navRepeat = 0; step = true }
        }
      }
    }
    if (step) {
      // Navigate Y is positive UP; rows run top to bottom.
      if (dy) this._selected = (this._selected - dy + 4) % 4
      if (dx) this._adjust(dx)
      this._refresh()
    }

    if (Input.started('Submit')) this._confirm()
    if (Input.started('Cancel')) this.close()
  }

  // ----- the maths --------------------------------------------------------------------------------

  /** Souls to buy every pending point, from the player's CURRENT level. */
  public pendingCost(): number {
    const p = this._player as any
    if (!p?.levelFor) return 0
    const from = p.level
    const to = p.levelFor(this._pending[0], this._pending[1], this._pending[2], this._pending[3])
    let cost = 0
    for (let l = from; l < to; l++) cost += p.levelCost(l)
    return cost
  }

  private _adjust(delta: number): void {
    const p = this._player as any
    if (!p) return
    const key = STATS[this._selected]
    const floor = p[key]
    const next = this._pending[this._selected] + delta
    if (next < floor || next > 99) return
    const before = this._pending[this._selected]
    this._pending[this._selected] = next
    if (delta > 0 && this.pendingCost() > (p.souls ?? 0)) {
      this._pending[this._selected] = before
      playSound(this, 'Menu Deny')
      return
    }
    playSound(this, 'Menu Tick')
    this._refresh()
  }

  private _confirm(): void {
    const p = this._player as any
    if (!p) return
    const cost = this.pendingCost()
    if (cost <= 0) return
    if (p.applyLevelUp?.(this._pending[0], this._pending[1], this._pending[2], this._pending[3], cost)) {
      playSound(this, 'Level Up')
      ;(this._gm as any)?.notice?.('Level up!')
    }
    this._resetPending()
    this._refresh()
  }

  private _resetPending(): void {
    const p = this._player as any
    this._pending = STATS.map(k => (p ? p[k] : 10))
  }

  private _refresh(): void {
    const p = this._player as any
    if (!p?.levelFor) return
    const level = p.levelFor(this._pending[0], this._pending[1], this._pending[2], this._pending[3])
    const cost = this.pendingCost()
    this._set('LevelText', 'Level  ' + p.level + (level !== p.level ? '  ->  ' + level : ''))
    this._set('SoulsText', 'Souls  ' + p.souls + (cost ? '  ->  ' + (p.souls - cost) : ''))
    this._set('CostText', 'Next level  ' + p.levelCost(level) + ' souls')

    const labels = ['Vigor', 'Endurance', 'Strength', 'Dexterity']
    labels.forEach((label, i) => {
      const row = this._find('Row_' + label) as any
      if (!row) return
      const changed = this._pending[i] !== p[STATS[i]]
      const value = this._find('Value', row) as UITextNode
      if (value) value.text = String(this._pending[i]) + (changed ? ' *' : '')
      const tint = i === this._selected ? this.selectedTint : this.rowTint
      row.tint = [tint[0], tint[1], tint[2], tint[3]]
    })

    const weapons: Node[] = p.weapons?.() ?? []
    const ar = weapons.map(w => (w as any).displayName + ' ' + ((w as any).attackRating?.(this._pending[2], this._pending[3]) ?? 0))
    this._set('Derived', 'HP ' + p.hpForVigor(this._pending[0]) + '    Stamina ' + p.staminaForEndurance(this._pending[1])
      + '\nAttack  ' + ar.join('   '))
  }

  private _set(name: string, text: string): void {
    const node = this._find(name) as UITextNode
    if (node && node.text !== text) node.text = text
  }

  private _find(name: string, root: Node = this): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(root)
  }
}

import { Input, Node, UIButtonNode, UIRootNode, UITextNode } from 'cleo'
import { playSound } from '@/Core/Scripts/SoulsAudio'

/**
 * A yes/no question over the game: "Enter the skull cave?". Attach to the `ConfirmDialog` node, a
 * screen-space UI Root authored hidden, on the player beside the bonfire menu:
 *
 *   ConfirmDialog
 *     Card
 *       Title, Body      uiText
 *       Yes, No          uiButton
 *
 * `ask(title, body, onYes)` opens it. Submit or Yes answers yes, Cancel or No answers no; the mouse can
 * click either. Gameplay input is off while it is open, and back on before `onYes` runs -- a scene
 * switch keeps the input maps as they are, so a dialog that loaded a scene while still holding Gameplay
 * off would leave the next scene unable to move.
 */
export default class SoulsConfirmDialogNode extends UIRootNode {
  public isOpen: boolean = false

  private _onYes: () => void = null
  private _openedAt: number = 0
  private _clock: number = 0

  onStart() {
    this.visible = false
    this.isOpen = false
    const yes = this._find('Yes') as UIButtonNode
    if (yes) yes.onPress = () => this._answer(true)
    const no = this._find('No') as UIButtonNode
    if (no) no.onPress = () => this._answer(false)
  }

  public ask(title: string, body: string, onYes: () => void): void {
    this._set('Title', title)
    this._set('Body', body)
    this._onYes = onYes
    this.isOpen = true
    this._openedAt = this._clock
    this.visible = true
    Input.disableMap('Gameplay')
    Input.releaseMouse()
    playSound(this, 'Menu Tick')
  }

  onUpdate(delta: number) {
    this._clock += delta
    if (!this.isOpen) return
    // Swallow the press that opened us (Interact may share a key with Submit).
    if (this._clock - this._openedAt < 0.2) return
    if (Input.started('Submit')) this._answer(true)
    else if (Input.started('Cancel')) this._answer(false)
  }

  private _answer(yes: boolean): void {
    if (!this.isOpen) return
    this.isOpen = false
    this.visible = false
    Input.enableMap('Gameplay')
    const then = this._onYes
    this._onYes = null
    if (yes) then?.()
  }

  private _set(name: string, text: string): void {
    const node = this._find(name) as UITextNode
    if (node) node.text = text
  }

  private _find(name: string, root: Node = this): Node {
    for (const child of root.children) {
      if (child.name === name) return child
      const found = this._find(name, child)
      if (found) return found
    }
    return null
  }
}

import { Game, Input, Node, UIButtonNode, UIRootNode } from 'cleo'

/**
 * Hollow Keep — the pause menu. Attach to the `PauseMenu` node, a screen-space UI Root authored hidden,
 * a child of the Player like the HUD and the bonfire menu.
 *
 *   Card
 *     Title                "PAUSED"                                 uiText
 *     Resume               back to the game                          uiButton
 *     Bonfire              return to the last bonfire rested at      uiButton
 *     Hint                 the controls line                         uiText
 *
 * Pause (P, Escape, or Start on a pad — the UI map) opens it: the game is paused with `Game.pause()`, so
 * physics, scripts, timers and animation all stop where they are. Pause or Cancel closes it; the mouse
 * can click either button.
 *
 * It listens in a LATE UPDATE (`scene.addLateUpdate`), not in onUpdate: while the game is paused no node's
 * onUpdate runs, so a menu that polled there could open but never close. Late updates run every frame,
 * paused or not, and input is read every frame too.
 *
 * It never opens over another menu (resting at a bonfire, a yes/no dialog) or while the player is dying,
 * nor in the moment just after one closes: Escape is also the bonfire menu's Cancel, and the press that
 * closes that menu must not open this one.
 */
export default class SoulsPauseMenuNode extends UIRootNode {
  /** Real seconds after another menu closes during which Pause is ignored (see above). */
  public reopenGuard: number = 0.25
  public isOpen: boolean = false

  private _gm: Node = null
  private _player: Node = null
  private _menus: Node[] = []
  private _stopListening: (() => void) | null = null
  /** Real time (seconds), counted in the late update, and when another menu was last seen open. */
  private _clock: number = 0
  private _otherMenuAt: number = -1

  onStart() {
    this.visible = false
    this.isOpen = false
    this._gm = this.findNode('GameManager')
    this._player = this.findNode('Player')
    // The other menus this must not open over: the bonfire menu and the yes/no dialog.
    this._menus = [
      this._player?.getChildByName('BonfireMenu')[0],
      this._player?.getChildByName('ConfirmDialog')[0],
      this.findNode('ConfirmDialog'),
    ].filter(n => !!n && n !== this)
    const resume = this._find('Resume') as UIButtonNode
    if (resume) resume.onPress = () => this.close()
    const bonfire = this._find('Bonfire') as UIButtonNode
    if (bonfire) bonfire.onPress = () => this._toBonfire()
    this._stopListening = this.scene?.addLateUpdate((_delta, unscaled) => this._listen(unscaled)) ?? null
  }

  onDespawn() {
    this._stopListening?.()
    this._stopListening = null
    if (this.isOpen) this.close()
  }

  /** Pause the game and show the menu. */
  public open(): void {
    if (this.isOpen) return
    this.isOpen = true
    this.visible = true
    Game.clearSlowMotion()
    Game.pause()
    Input.disableMap('Gameplay')
    Input.releaseMouse()
  }

  /** Hide the menu and carry on. */
  public close(): void {
    if (!this.isOpen) return
    this.isOpen = false
    this.visible = false
    Game.resume()
    // Another menu may have been opened underneath by a script; it keeps the Gameplay map off.
    if (!this._otherMenuOpen()) Input.enableMap('Gameplay')
    this._otherMenuAt = this._clock
  }

  private _listen(unscaled: number): void {
    this._clock += unscaled
    if (this._otherMenuOpen()) this._otherMenuAt = this._clock
    if (this.isOpen) {
      if (Input.started('Pause') || Input.started('Cancel')) this.close()
      else if (Input.started('Submit')) this.close()
      return
    }
    if (!Input.started('Pause') || !this._canPause()) return
    this.open()
  }

  private _canPause(): boolean {
    if (Game.isPaused) return false                        // paused by someone else (the editor)
    if (this._otherMenuOpen()) return false
    if (this._clock - this._otherMenuAt < this.reopenGuard) return false
    const p = this._player as any
    if (p?.isDead) return false
    return true
  }

  private _otherMenuOpen(): boolean {
    return this._menus.some(m => (m as any).isOpen)
  }

  private _toBonfire(): void {
    this.close()
    ;(this._gm as any)?.respawnAtBonfire?.()
  }

  private _find(name: string, under: Node = this): Node {
    for (const child of under.children) {
      if (child.name === name) return child
      const deeper = this._find(name, child)
      if (deeper) return deeper
    }
    return null
  }
}

